package com.cyancoder.media.controller;import com.cyancoder.media.model.MediaUploadEntity;import com.cyancoder.media.service.MediaOperatorService;import org.springframework.core.io.Resource;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/public/media/content") public class PublicMediaContentController{private final MediaOperatorService service;public PublicMediaContentController(MediaOperatorService s){service=s;}@GetMapping("/{key}")public ResponseEntity<Resource> content(@PathVariable String key){MediaUploadEntity u=service.publicMetadata(key);return ResponseEntity.ok().cacheControl(CacheControl.maxAge(java.time.Duration.ofHours(1)).cachePublic()).contentType(MediaType.parseMediaType(u.getMimeType())).header(HttpHeaders.CONTENT_DISPOSITION,"inline; filename*=UTF-8''"+org.springframework.web.util.UriUtils.encodePathSegment(u.getOriginalFileName(),java.nio.charset.StandardCharsets.UTF_8)).body(service.publicContent(key));}}
